import React from "react";
import { fireEvent, render, screen, waitFor } from "@testing-library/react";
import { MatrixClient } from "matrix-js-sdk/src/client";
import { Room } from "matrix-js-sdk/src/models/room";
import { RoomMember } from "matrix-js-sdk/src/models/room-member";

import { Pill, PillType, pillRoomNotifLen, pillRoomNotifPos } from "../../../../src/components/views/elements/Pill";
import dis from "../../../../src/dispatcher/dispatcher";
import { Action } from "../../../../src/dispatcher/actions";
import { mkStubRoom, stubClient } from "../../../test-utils";

describe("<Pill />", () => {
    let client: MatrixClient;
    let room: Room;

    beforeEach(() => {
        client = stubClient();
        room = mkStubRoom("!room:example.com", "The Room", client);
        (client.getRoom as jest.Mock).mockImplementation((id: string) => (id === room.roomId ? room : null));
        (client.getRooms as jest.Mock).mockReturnValue([room]);
    });

    afterEach(() => {
        jest.restoreAllMocks();
    });

    it("finds the first @room token and exposes its length", () => {
        expect(pillRoomNotifPos("hello @room and @room")).toBe(6);
        expect(pillRoomNotifPos("hello room")).toBe(-1);
        expect(pillRoomNotifLen()).toBe(5);
    });

    it("renders nothing when no target can be inferred", () => {
        const { container, rerender } = render(<Pill url="https://example.com/" inMessage />);
        expect(container).toBeEmptyDOMElement();

        rerender(<Pill type={PillType.UserMention} />);
        expect(container).toBeEmptyDOMElement();
    });

    it("keeps the exact room permalink and pill DOM shape in messages", () => {
        const url = "https://matrix.to/#/!room:example.com?via=example.com&via=other.com";
        const { container } = render(<Pill url={url} inMessage />);
        const wrapper = container.querySelector("bdi");
        const link = wrapper?.firstElementChild;

        expect(link).toHaveClass("mx_Pill", "mx_RoomPill");
        expect(link).toHaveAttribute("href", url);
        expect(link).toHaveTextContent("The Room");
        expect(link?.firstElementChild).toHaveClass("mx_Pill_linkText");
    });

    it("uses a span outside messages and shows @room with the current room avatar", () => {
        const { container } = render(<Pill type={PillType.AtRoomMention} room={room} shouldShowPillAvatar />);
        const wrapper = container.querySelector("bdi");
        const pill = wrapper?.firstElementChild;

        expect(pill?.tagName).toBe("SPAN");
        expect(pill).toHaveClass("mx_Pill", "mx_AtRoomPill");
        expect(pill).toHaveTextContent("@room");
        expect(pill?.children[0]).toHaveAttribute("aria-hidden", "true");
        expect(pill?.children[1]).toHaveClass("mx_Pill_linkText");
    });

    it("shows an unresolved room alias as its raw alias", () => {
        (client.getRooms as jest.Mock).mockReturnValue([]);
        const url = "https://matrix.to/#/#unknown:example.com";
        render(<Pill url={url} inMessage />);

        expect(screen.getByText("#unknown:example.com").closest("a")).toHaveClass("mx_Pill", "mx_RoomPill");
        expect(screen.getByText("#unknown:example.com").closest("a")).toHaveAttribute("href", url);
    });

    it("marks a resolved Space as a Space pill", () => {
        jest.spyOn(room, "isSpaceRoom").mockReturnValue(true);
        const { container } = render(<Pill url="https://matrix.to/#/!room:example.com" inMessage />);

        expect(container.querySelector(".mx_Pill")).toHaveClass("mx_SpacePill");
    });

    it("falls back to the full user ID when no display name is available", async () => {
        const userId = "@alice:example.com";
        (room.getMember as jest.Mock).mockReturnValue(null);
        (client.getProfileInfo as jest.Mock).mockResolvedValue({});
        const url = `https://matrix.to/#/${userId}`;
        const { container } = render(<Pill url={url} room={room} inMessage shouldShowPillAvatar />);

        await waitFor(() => expect(container.querySelector(".mx_Pill_linkText")).toHaveTextContent(userId));
        expect(container.querySelector("a.mx_UserPill")).toHaveAttribute("href", url);
        expect(container.querySelector(".mx_BaseAvatar")).not.toBeInTheDocument();
    });

    it("shows the raw room ID in a tooltip while hovered", () => {
        const { container } = render(<Pill url="https://matrix.to/#/!room:example.com" inMessage />);
        const pill = container.querySelector(".mx_Pill")!;

        fireEvent.mouseOver(pill);
        expect(document.querySelector(".mx_Tooltip_visible")).toHaveTextContent(room.roomId);
        fireEvent.mouseLeave(pill);
        expect(document.querySelector(".mx_Tooltip_visible")).not.toBeInTheDocument();
    });

    it("dispatches the resolved member when a user pill is clicked in a message", () => {
        const userId = client.getUserId()!;
        const member = new RoomMember(room.roomId, userId);
        member.name = "Me";
        member.rawDisplayName = "Me";
        (room.getMember as jest.Mock).mockReturnValue(member);
        const dispatch = jest.spyOn(dis, "dispatch").mockImplementation(jest.fn());
        const { container } = render(<Pill url={`https://matrix.to/#/${userId}`} room={room} inMessage />);
        const pill = container.querySelector("a.mx_Pill")!;

        expect(pill).toHaveClass("mx_UserPill", "mx_UserPill_me");
        fireEvent.click(pill);
        expect(dispatch).toHaveBeenCalledWith({ action: Action.ViewUser, member });
    });
});

