import React, { ReactElement, useEffect, useMemo, useState } from "react";
import { Room } from "matrix-js-sdk/src/models/room";
import { RoomMember } from "matrix-js-sdk/src/models/room-member";
import { MatrixEvent } from "matrix-js-sdk/src/models/event";
import { logger } from "matrix-js-sdk/src/logger";

import { MatrixClientPeg } from "../MatrixClientPeg";
import { getPrimaryPermalinkEntity } from "../utils/permalinks/Permalinks";
import dis from "../dispatcher/dispatcher";
import { Action } from "../dispatcher/actions";
import { PillType } from "../components/views/elements/PillType";
import RoomAvatar from "../components/views/avatars/RoomAvatar";
import MemberAvatar from "../components/views/avatars/MemberAvatar";
import { ButtonEvent } from "../components/views/elements/AccessibleButton";

export interface UsePermalinkArgs {
    room?: Room;
    type?: PillType;
    url?: string;
}

export interface UsePermalinkResult {
    avatar: ReactElement | null;
    text: string | null;
    onClick: ((e: ButtonEvent) => void) | null;
    resourceId: string | null;
    type: PillType | "space" | null;
}

const emptyResult: UsePermalinkResult = {
    avatar: null,
    text: null,
    onClick: null,
    resourceId: null,
    type: null,
};

/** Resolve a mention to the information needed to render a pill. */
export function usePermalink({ room, type, url }: UsePermalinkArgs): UsePermalinkResult {
    const entityId = useMemo(() => (url ? getPrimaryPermalinkEntity(url) : null), [url]);
    const inferredType =
        entityId?.[0] === "@" && entityId !== "@room"
            ? PillType.UserMention
            : entityId?.[0] === "!" || entityId?.[0] === "#"
              ? PillType.RoomMention
              : null;
    const effectiveType = type === PillType.AtRoomMention ? type : type ?? inferredType;
    const validEntity = effectiveType === inferredType && !!entityId;

    const localMember =
        validEntity && effectiveType === PillType.UserMention ? room?.getMember(entityId) : undefined;
    const fallbackMember = useMemo(
        () =>
            validEntity && effectiveType === PillType.UserMention && !localMember
                ? new RoomMember(null, entityId)
                : null,
        [effectiveType, entityId, localMember, validEntity],
    );
    const [profile, setProfile] = useState<{ userId: string; member: RoomMember } | null>(null);

    useEffect(() => {
        if (!fallbackMember) return;

        let active = true;
        MatrixClientPeg.get()
            .getProfileInfo(fallbackMember.userId)
            .then((response) => {
                if (!active) return;

                const member = new RoomMember(null, fallbackMember.userId);
                member.name = response.displayname || member.userId;
                member.rawDisplayName = response.displayname || member.userId;
                member.events.member = {
                    getContent: () => ({ avatar_url: response.avatar_url }),
                    getDirectionalContent: () => ({ avatar_url: response.avatar_url }),
                } as MatrixEvent;
                setProfile({ userId: member.userId, member });
            })
            .catch((error) => {
                logger.error("Could not retrieve profile data for " + fallbackMember.userId + ":", error);
            });

        return () => {
            active = false;
        };
    }, [fallbackMember]);

    if (effectiveType === PillType.AtRoomMention) {
        return {
            avatar: room?.getMxcAvatarUrl() ? <RoomAvatar room={room} width={16} height={16} aria-hidden="true" /> : null,
            text: "@room",
            onClick: null,
            resourceId: room?.roomId ?? null,
            type: PillType.AtRoomMention,
        };
    }

    if (!validEntity) return emptyResult;

    if (effectiveType === PillType.RoomMention) {
        const resolvedRoom =
            entityId[0] === "#"
                ? MatrixClientPeg.get()
                      .getRooms()
                      .find((candidate) =>
                          candidate.getCanonicalAlias() === entityId || candidate.getAltAliases().includes(entityId),
                      )
                : MatrixClientPeg.get().getRoom(entityId);

        return {
            avatar: resolvedRoom?.getMxcAvatarUrl() ? (
                <RoomAvatar room={resolvedRoom} width={16} height={16} aria-hidden="true" />
            ) : null,
            text: resolvedRoom?.name || entityId,
            onClick: null,
            resourceId: entityId,
            type: resolvedRoom?.isSpaceRoom() ? "space" : PillType.RoomMention,
        };
    }

    if (effectiveType === PillType.UserMention) {
        const member = localMember ?? (profile?.userId === entityId ? profile.member : fallbackMember);
        if (!member) return emptyResult;

        return {
            avatar: member.getMxcAvatarUrl() ? (
                <MemberAvatar member={member} width={16} height={16} aria-hidden="true" hideTitle />
            ) : null,
            text: member.rawDisplayName || member.name || entityId,
            onClick: (e: ButtonEvent): void => {
                e.preventDefault();
                dis.dispatch({ action: Action.ViewUser, member });
            },
            resourceId: entityId,
            type: PillType.UserMention,
        };
    }

    return emptyResult;
}

