import React, { useState } from "react";
import classNames from "classnames";
import { Room } from "matrix-js-sdk/src/models/room";

import { MatrixClientPeg } from "../../../MatrixClientPeg";
import MatrixClientContext from "../../../contexts/MatrixClientContext";
import { usePermalink } from "../../../hooks/usePermalink";
import Tooltip, { Alignment } from "./Tooltip";
import { PillType } from "./PillType";

export { PillType } from "./PillType";

export interface PillProps {
    type?: PillType;
    url?: string;
    inMessage?: boolean;
    room?: Room;
    shouldShowPillAvatar?: boolean;
}

export function pillRoomNotifPos(text: string): number {
    return text.indexOf("@room");
}

export function pillRoomNotifLen(): number {
    return "@room".length;
}

export function Pill({ type, url, inMessage, room, shouldShowPillAvatar }: PillProps): JSX.Element | null {
    const [hovered, setHovered] = useState(false);
    const permalink = usePermalink({ type, url, room });
    if (!permalink.type || !permalink.text) return null;

    const classes = classNames("mx_Pill", {
        mx_UserPill: permalink.type === PillType.UserMention,
        mx_UserPill_me:
            permalink.type === PillType.UserMention && permalink.resourceId === MatrixClientPeg.get().getUserId(),
        mx_RoomPill: permalink.type === PillType.RoomMention || permalink.type === "space",
        mx_SpacePill: permalink.type === "space",
        mx_AtRoomPill: permalink.type === PillType.AtRoomMention,
    });
    const content = (
        <>
            {shouldShowPillAvatar && permalink.avatar}
            <span className="mx_Pill_linkText">{permalink.text}</span>
            {hovered && permalink.resourceId && <Tooltip label={permalink.resourceId} alignment={Alignment.Right} />}
        </>
    );
    const hoverProps = {
        onMouseOver: (): void => setHovered(true),
        onMouseLeave: (): void => setHovered(false),
    };

    return (
        <bdi>
            <MatrixClientContext.Provider value={MatrixClientPeg.get()}>
                {inMessage && url ? (
                    <a className={classes} href={url} onClick={permalink.onClick ?? undefined} {...hoverProps}>
                        {content}
                    </a>
                ) : (
                    <span className={classes} {...hoverProps}>
                        {content}
                    </span>
                )}
            </MatrixClientContext.Provider>
        </bdi>
    );
}

